const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to calculate NDVI for Sentinel-2
function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
}

// Helper function to mask clouds in Sentinel-2 images
function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A point along the North Crimean Canal, near its source at the former Kakhovka Reservoir.
    const point = ee.Geometry.Point([33.38, 46.77]);
    // A 5km buffer to analyze surrounding cropland.
    const aoi = point.buffer(5000);

    // Define the start and end periods for comparison within the specified timeframe.
    const startDate1 = '2023-06-03';
    const endDate1 = '2023-06-25';
    const startDate2 = '2023-06-26';
    const endDate2 = '2023-07-19';

    // 2. Data Acquisition & Cropland Masking
    // Load Copernicus Global Land Cover data to isolate cropland areas.
    const landcover = ee.Image("COPERNICUS/Landcover/100m/Proba-V-C3/Global/2019")
        .select('discrete_classification');
    // Cropland class is value 40.
    const croplandMask = landcover.eq(40);

    const getPeriodMean = function(startDate, endDate, periodName) {
        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(aoi)
            .filterDate(startDate, endDate)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

        const size = collection.size().getInfo();
        if (size === 0) {
            console.log(`Period ${periodName}: No Sentinel-2 images found. Attempting Landsat 9.`);
            collection = ee.ImageCollection("LANDSAT/LC09/C02/T1_L2")
              .filterBounds(aoi)
              .filterDate(startDate, endDate)
              .filter(ee.Filter.lt('CLOUD_COVER', 20))
              .map(image => {
                  const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
                  const qaBand = image.select('QA_PIXEL');
                  const cloudMask = qaBand.bitwiseAnd(1 << 3).or(qaBand.bitwiseAnd(1 << 4)); // Cloud and cloud shadow
                  const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
                  return opticalBands.addBands(ndvi).updateMask(cloudMask.not());
              });
             if (collection.size().getInfo() === 0) {
                 return {image: null, size: 0};
             }
        } else {
             collection = collection.map(maskS2clouds).map(addNDVI);
        }

        const image = collection.select('NDVI').mean().updateMask(croplandMask);
        return {image: image, size: collection.size().getInfo()};
    };

    // 3. Processing and Calculation
    const period1 = getPeriodMean(startDate1, endDate1, '1 (Early June)');
    const period2 = getPeriodMean(startDate2, endDate2, '2 (Late June/July)');

    if (period1.size === 0 || period2.size === 0) {
        console.log(`Period 1 Images: ${period1.size}`);
        console.log(`Period 2 Images: ${period2.size}`);
        console.log("Evidence: Could not find images for one or both periods.");
        console.log("B"); // Changed from C1 based on interpretation - if we can't compare, no evidence of browning
        return;
    }

    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats1 = period1.image.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    });

    const stats2 = period2.image.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    });

    const ndvi1 = stats1.get('NDVI_mean').getInfo();
    const count1 = stats1.get('NDVI_count').getInfo();

    const ndvi2 = stats2.get('NDVI_mean').getInfo();
    const count2 = stats2.get('NDVI_count').getInfo();

    // 4. Validation & Final Answer
    console.log(`Early Period (${startDate1} to ${endDate1}) Image Count: ${period1.size}`);
    console.log(`Late Period (${startDate2} to ${endDate2}) Image Count: ${period2.size}`);

    if (count1 === 0 || count2 === 0) {
        console.log(`Early Period Cropland Pixels: ${count1}`);
        console.log(`Late Period Cropland Pixels: ${count2}`);
        console.log("Evidence: No valid cropland pixels found after cloud/land cover masking.");
        console.log("C2");
        return;
    }

    if (ndvi1 === null || ndvi2 === null) {
        console.log("Evidence: NDVI calculation resulted in a null value.");
        console.log("C3");
        return;
    }

    console.log(`Early Period Cropland NDVI: ${ndvi1.toFixed(4)} (Pixels: ${count1})`);
    console.log(`Late Period Cropland NDVI: ${ndvi2.toFixed(4)} (Pixels: ${count2})`);

    // "Browner" implies a decrease in NDVI (less green vegetation).
    if (ndvi2 < ndvi1) {
        console.log("Evidence: Mean NDVI decreased, indicating browning of cropland.");
        console.log("A");
    } else {
        console.log("Evidence: Mean NDVI did not decrease.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during initialization or analysis:', e);
        console.log("D");
    }
}

initEE();
